package com.cryptostrategy.platform.leaderboard.internal;import com.cryptostrategy.platform.evaluation.api.model.*;import com.cryptostrategy.platform.experiment.api.ExperimentId;import com.cryptostrategy.platform.leaderboard.api.model.*;import java.time.Instant;import java.util.*;public final class TopKProjector{public LeaderboardRevision project(ExperimentId experiment,RankingVersion ranking,long revisionNumber,int topK,List<EvaluationResult> input){if(topK<1)throw new IllegalArgumentException("topK");Set<EvaluationResultId> seen=new HashSet<>();for(var e:input)if(!e.experimentId().equals(experiment)||!seen.add(e.evaluationResultId()))throw new IllegalArgumentException("Cross-experiment or duplicate evaluation");List<EvaluationResult> sorted=input.stream().filter(EvaluationResult::leaderboardEligible).filter(e->e.rankingVersion().equals(ranking)).sorted(Comparator.comparing(EvaluationResult::overallScore).reversed().thenComparing(EvaluationResult::maximumDrawdown).thenComparing(EvaluationResult::fingerprint)).limit(topK).toList();LeaderboardRevisionId id=LeaderboardRevisionId.generate();List<LeaderboardEntry> entries=new ArrayList<>();for(int i=0;i<sorted.size();i++){var e=sorted.get(i);entries.add(new LeaderboardEntry(id,experiment,i+1,e.evaluationResultId(),e.overallScore(),e.maximumDrawdown(),e.fingerprint()));}String fp=new LeaderboardFingerprintV1().calculate(experiment,ranking,entries);return new LeaderboardRevision(id,experiment,revisionNumber,topK,ranking,entries,fp,Instant.now());}}
